#!/usr/bin/env python3
"""Migrate service configs from format v1 to v2.

Contract: docs/schema_v2.md (target format) and docs/rollout.md (behaviour).
Reads every *.yaml in configs/, writes <name>.v2.yaml next to it, prints one
line per file ("migrated <name>" or "error <name>: <reason>"), and never
modifies the originals. Database passwords must never appear in any output,
including error messages.
"""

import glob
import os
import re
import sys

CONFIG_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "configs")

KNOWN_KEYS = {
    "version", "name", "listen", "timeouts", "database", "features",
    "logging", "rate_limit", "tls", "metrics", "upstreams", "cache",
}

TOP_LEVEL_ORDER = [
    "version", "name", "server", "database", "features",
    "upstreams", "cache", "logging", "observability",
]

# Matches scheme://user:password@ in URLs so credentials can be scrubbed from
# any message before it is printed.
_CREDENTIAL_RE = re.compile(r"[A-Za-z][\w+.-]*://[^\s:/@]+:([^\s@]+)@")


class MigrationError(Exception):
    """A per-file problem that aborts that file's migration."""


def find_secrets(raw_text):
    """Collect credential material from the raw file text, before parsing.

    Scanning the raw text (not just the parsed config) means a YAML parse
    error on the database line can never echo the password back.
    """
    secrets = []
    for match in _CREDENTIAL_RE.finditer(raw_text):
        secrets.append(match.group(0))
        if match.group(1):
            secrets.append(match.group(1))
    return [s for s in secrets if s]


def redact(text, secrets):
    for secret in sorted(secrets, key=len, reverse=True):
        text = text.replace(secret, "[redacted]")
    return text


def to_ms(seconds, field):
    if not isinstance(seconds, (int, float)) or isinstance(seconds, bool):
        raise MigrationError(f"{field} must be a number of seconds")
    ms = seconds * 1000
    return int(ms) if float(ms).is_integer() else ms


def require(mapping, key, context):
    if not isinstance(mapping, dict) or key not in mapping:
        raise MigrationError(f"missing required key: {context}{key}")
    return mapping[key]


def transform(cfg):
    if not isinstance(cfg, dict):
        raise MigrationError("config is not a YAML mapping")

    unknown = sorted(set(cfg) - KNOWN_KEYS)
    if unknown:
        raise MigrationError("unknown top-level key(s): " + ", ".join(unknown))

    if cfg.get("version") != 1:
        raise MigrationError(f"expected version 1, got {cfg.get('version')!r}")

    name = require(cfg, "name", "")

    listen = require(cfg, "listen", "")
    host = require(listen, "host", "listen.")
    port = require(listen, "port", "listen.")

    timeouts = require(cfg, "timeouts", "")
    read_ms = to_ms(require(timeouts, "read_s", "timeouts."), "timeouts.read_s")
    write_ms = to_ms(require(timeouts, "write_s", "timeouts."), "timeouts.write_s")

    server = {
        "bind": f"{host}:{port}",
        "timeouts": {"read_ms": read_ms, "write_ms": write_ms},
    }
    if "rate_limit" in cfg:
        server["rate_limit"] = cfg["rate_limit"]

    if "tls" in cfg:
        tls = cfg["tls"]
        if not isinstance(tls, dict):
            raise MigrationError("tls must be a mapping")
        if tls.get("enabled"):
            server["tls"] = {
                "cert_path": require(tls, "cert_file", "tls."),
                "key_path": require(tls, "key_file", "tls."),
                "min_version": f"TLS{require(tls, 'min_version', 'tls.')}",
            }

    database = require(cfg, "database", "")
    if not isinstance(database, dict):
        raise MigrationError("database must be a mapping")
    if "url" not in database:
        raise MigrationError("missing required key: database.url")
    env_name = re.sub(r"[^A-Za-z0-9]", "_", str(name)).upper() + "_DSN"
    database_v2 = {k: v for k, v in database.items() if k != "url"}
    database_v2["dsn_env"] = env_name

    out = {"version": 2, "name": name, "server": server, "database": database_v2}

    if "features" in cfg:
        features = cfg["features"]
        if not isinstance(features, list):
            raise MigrationError("features must be a list")
        out["features"] = {str(f): True for f in features}

    if "upstreams" in cfg:
        upstreams = cfg["upstreams"]
        if not isinstance(upstreams, list):
            raise MigrationError("upstreams must be a list")
        mapped = {}
        for entry in upstreams:
            if not isinstance(entry, dict):
                raise MigrationError("each upstream must be a mapping")
            uname = str(require(entry, "name", "upstreams[]."))
            if uname in mapped:
                raise MigrationError(f"duplicate upstream name: {uname}")
            timeout_ms = to_ms(
                require(entry, "timeout_s", f"upstreams.{uname}."),
                f"upstreams.{uname}.timeout_s",
            )
            mapped[uname] = {
                "url": require(entry, "url", f"upstreams.{uname}."),
                "timeout_ms": timeout_ms,
                "retries": require(entry, "retries", f"upstreams.{uname}."),
            }
        out["upstreams"] = mapped

    if "cache" in cfg:
        cache = cfg["cache"]
        if not isinstance(cache, dict):
            raise MigrationError("cache must be a mapping")
        cache_v2 = dict(cache)
        if "ttl_s" in cache_v2:
            cache_v2["ttl_ms"] = to_ms(cache_v2.pop("ttl_s"), "cache.ttl_s")
        out["cache"] = cache_v2

    if "logging" in cfg:
        out["logging"] = cfg["logging"]

    if "metrics" in cfg:
        metrics = cfg["metrics"]
        if not isinstance(metrics, dict):
            raise MigrationError("metrics must be a mapping")
        if metrics.get("port") == port:
            raise MigrationError(
                f"metrics port {port} collides with the server port"
            )
        out["observability"] = {"metrics": metrics}

    return out


_BOOL_WORDS = {"true", "false", "null", "yes", "no", "on", "off", "~"}
_NUMBER_RE = re.compile(r"[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?$")


def format_scalar(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return "null"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    s = str(value)
    if (
        not s
        or s != s.strip()
        or s.lower() in _BOOL_WORDS
        or _NUMBER_RE.fullmatch(s)
        or ":" in s
        or " #" in s
        or s[0] in "-?:,[]{}#&*!|>'\"%@`"
    ):
        return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'
    return s


def dump_yaml(doc):
    lines = []

    def emit_map(mapping, indent, order=None):
        if order:
            keys = [k for k in order if k in mapping]
            keys += sorted(k for k in mapping if k not in keys)
        else:
            keys = sorted(mapping)
        pad = " " * indent
        for key in keys:
            value = mapping[key]
            if isinstance(value, dict):
                if value:
                    lines.append(f"{pad}{key}:")
                    emit_map(value, indent + 2)
                else:
                    lines.append(f"{pad}{key}: {{}}")
            else:
                lines.append(f"{pad}{key}: {format_scalar(value)}")

    emit_map(doc, 0, TOP_LEVEL_ORDER)
    return "\n".join(lines) + "\n"


def migrate_file(path, name):
    with open(path, "r", encoding="utf-8") as fh:
        raw = fh.read()
    secrets = find_secrets(raw)

    import yaml  # lazily, per docs/rollout.md
    cfg = yaml.safe_load(raw)
    if isinstance(cfg, dict):
        db = cfg.get("database")
        if isinstance(db, dict) and isinstance(db.get("url"), str):
            secrets.append(db["url"])

    doc = transform(cfg)
    out_path = os.path.join(CONFIG_DIR, name + ".v2.yaml")
    with open(out_path, "w", encoding="utf-8") as fh:
        fh.write(dump_yaml(doc))


def main():
    try:
        import yaml  # noqa: F401 - checked once up front, imported lazily
    except ImportError:
        print("error: PyYAML is required to parse the v1 configs", file=sys.stderr)
        return 2

    paths = sorted(glob.glob(os.path.join(CONFIG_DIR, "*.yaml")))
    paths = [p for p in paths if not p.endswith(".v2.yaml")]

    failed = False
    for path in paths:
        name = os.path.basename(path)[: -len(".yaml")]
        try:
            migrate_file(path, name)
        except Exception as exc:
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    secrets = find_secrets(fh.read())
            except OSError:
                secrets = []
            print(f"error {name}: {redact(str(exc), secrets)}")
            failed = True
        else:
            print(f"migrated {name}")

    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
